<?php
declare(strict_types=1);
define('XAR_SPECIAL_FIXTURE_ONLY',true);
require __DIR__.'/tactical-special-effects.php';
$specialChecks=0;
const WRENCH_TEMPLATE='v370-template-89b3acc87a18f696747bdae1';
$db=specialFixture();$c=$db->payload('character:character-player');$c['name']='Nom arbitraire sans personnage';$c['specialSuccessStock']=2;$db->put('character:character-player',$c);
$source=synchronizeOnlineCharacterToken($db->payload('token:scene-one:token-player'),$c);$source['x']=20;$db->put('token:scene-one:token-player',$source);
$target=$db->payload('token:scene-one:token-monster');$target['x']=30;$db->put('token:scene-one:token-monster',$target);
$equipment=['version'=>1,'kind'=>'weapon','hands'=>1,'formula'=>'1d25+6','damageType'=>'physical','reach'=>'melee','finesse'=>false,'projectile'=>false];
$db->put('items',normalizeItemStore(['version'=>1,'templates'=>[['id'=>WRENCH_TEMPLATE,'name'=>'Nom arbitraire','kind'=>'object','equipment'=>$equipment]],'instances'=>[['id'=>'actual-wrench','templateId'=>WRENCH_TEMPLATE,'revision'=>1,'location'=>['kind'=>'inventory','characterId'=>'character-player']]],'equipmentLoadouts'=>['character-player'=>['sets'=>[],'equippedItemIds'=>['actual-wrench'],'activeSetId'=>'']]]));
$before=$db->payload('items');$request='wrench-'.randomToken(20);
$args=['sceneId'=>'scene-one','sourceTokenId'=>'token-player','targetTokenId'=>'token-monster','attackKind'=>'weapon','attackId'=>'equipment-actual-wrench','statId'=>'character-stat-force','opposed'=>false,'requestId'=>$request,'useJoker'=>true,'visualPresetId'=>'ethereal-dash-cross'];
$result=runCommand($db,'token.attack',$args);specialCheck($result->status===200,'Physical object attack accepted: '.json_encode($result->body));
$attack=$result->body['attack'];specialCheck($attack['appliedDamage']>=7&&$attack['appliedDamage']<=31,'Actual 1d25+6 damage remains unchanged');
$canonical=array_values(array_filter($db->payload('activity')['attackReceipts'],static fn($receipt)=>$receipt['attack']['id']===$attack['id']))[0]['attack'];
specialCheck($canonical['damage']['formula']==='1d25+6'&&$canonical['damageType']==='physical','Physical formula is preserved');
$events=$db->payload('activity')['abilityCueEvents'];$cue=$events[0]['completionCue'];
specialCheck(count($events)===1&&$cue['spell']['presetId']==='battle-wrench-strike','Only the actual template chooses the basic visual');
specialCheck($cue['spell']['sourceTokenId']==='token-player'&&$cue['spell']['targetTokenId']==='token-monster','Correct actual source and target');
specialCheck($cue['spell']['source']==['x'=>20,'y'=>50,'size'=>40]&&$cue['spell']['targetPoint']==['x'=>30,'y'=>50,'size'=>40],'Normal token footprints are retained');
specialCheck(!isset($cue['spell']['movementDash'])&&$cue['sound']===null,'Neither a dash nor any sound is introduced');
specialCheck(applicationMeleeVisualCatalogue()['battle-wrench-strike']===950,'Animation duration matches the catalogue');
specialCheck($db->payload('items')===$before,'Physical object and hands are unchanged');
specialCheck(($before['templates'][0]['equipment']??null)==$equipment,'One hand, melee, physical, nonprojectile mechanics are unchanged');
$again=runCommand($db,'token.attack',$args);specialCheck($again->status===200&&!empty($again->body['deduplicated']),'Retry reuses its attack receipt');specialCheck($db->payload('activity')['abilityCueEvents']===$events,'Retry never repeats the animation');

$cloneResponse=runCommand($db,'token.clone',['sceneId'=>'scene-one','tokenId'=>'token-player','requestId'=>'wrench-clone-'.randomToken(18)],true);specialCheck(in_array($cloneResponse->status,[200,201],true),'Real independent clone accepted: '.json_encode($cloneResponse->body));
$clone=$cloneResponse->body['token'];$cloneId=$clone['id'];$items=$db->payload('items');$loadout=$items['equipmentLoadouts']['unit_'.$cloneId];specialCheck(count($loadout['equippedItemIds'])===1&&$loadout['equippedItemIds'][0]!=='actual-wrench','Independent clone owns a distinct physical object');
$cloneItem=array_values(array_filter($items['instances'],static fn($item)=>$item['id']===$loadout['equippedItemIds'][0]))[0];specialCheck($cloneItem['templateId']===WRENCH_TEMPLATE,'Cloned physical object keeps only its shared model');
$clonedToken=$db->payload('token:scene-one:'.$cloneId);$clonedToken['x']=21;$clonedToken['specialSuccessStock']=1;$db->put('token:scene-one:'.$cloneId,$clonedToken);
$unequipped=runCommand($db,'item.equipment.equip',['requestId'=>'wrench-unarmed-'.randomToken(18),'characterId'=>'character-player','itemIds'=>[],'expectedLoadout'=>$db->payload('items')['equipmentLoadouts']['character-player']],true);
specialCheck($unequipped->status===200,'The original owner can really remove the tool from their hands');
$refused=runCommand($db,'token.attack',[...$args,'requestId'=>'wrench-disarmed-'.randomToken(18),'useJoker'=>false]);specialCheck($refused->status===404&&($refused->body['code']??'')==='attack_weapon_missing','Owner cannot attack through a stale row after the physical weapon is unequipped');specialCheck($db->payload('activity')['abilityCueEvents']===$events,'Unarmed refusal adds no effect');
$copied=runCommand($db,'token.attack',[...$args,'requestId'=>'wrench-copy-'.randomToken(18),'sourceTokenId'=>$cloneId,'attackId'=>'equipment-'.$cloneItem['id']]);specialCheck($copied->status===200,'Independent clone attacks with its own item: '.json_encode($copied->body));specialCheck($copied->body['attack']['appliedDamage']>=7&&$copied->body['attack']['appliedDamage']<=31,'Clone keeps the same physical damage formula');
$events=$db->payload('activity')['abilityCueEvents'];$last=$events[array_key_last($events)]['completionCue']['spell'];specialCheck($last['presetId']==='battle-wrench-strike'&&$last['sourceTokenId']===$cloneId&&$last['source']['x']==21,'Clone visual uses its own source and template');
$stored=array_values(array_filter($db->payload('activity')['attackReceipts'],static fn($receipt)=>$receipt['attack']['id']===$copied->body['attack']['id']))[0]['attack'];
$map=['naturalWidth'=>1000,'naturalHeight'=>1000,'tokens'=>[$clonedToken,$target]];$context=['map'=>$map,'items'=>$db->payload('items')];
specialCheck(applicationTrustedMeleeVisual($stored,$context)['presetId']==='battle-wrench-strike','Canonical cloned receipt resolves its current item');
foreach([['projectile'=>true],['reach'=>'ranged']] as $change)specialCheck(applicationTrustedMeleeVisual([...$stored,'echoAttackContext'=>[...$stored['echoAttackContext'],...$change]],$context)===null,'Projectile and ranged weapons never borrow the tool visual');
specialCheck(applicationTrustedMeleeVisual($stored,[...$context,'items'=>['instances'=>[]]])===null,'An absent physical object cannot be substituted');
$public=['sceneId'=>'scene-one','layerId'=>'ground','sourceTokenId'=>$cloneId,'visibleTokenIds'=>[$cloneId],'visible'=>static fn()=>true];specialCheck(applicationPublicSpellVisual($last,$public)===null,'No animation discloses an invisible victim');
echo json_encode(['ok'=>true,'checks'=>$specialChecks,'productionAccess'=>false],JSON_THROW_ON_ERROR).PHP_EOL;
